import * as React from "react";
import {
	Button,
	AppBar,
	Toolbar,
	MenuList,
	MenuListItem,
	Separator,
	Avatar,
} from "react95";
import { ThemeProvider } from "styled-components";
import scrollTo from "../utils/scrollTo";

import water from "react95/dist/themes/water";

import ProfileImage from "../../images/me.png";
import styles from "../../css/HeadBar.css";

const openLink = (url, name = "_blank") => {
	window.open(url, name);
};

function Menu() {
	const [isOpen, setIsOpen] = React.useState(false);

	function handleClick() {
		setIsOpen(!isOpen);
	}

	function handleClose() {
		setIsOpen(false);
	}

	return (
		<div>
			{isOpen && (
				<MenuList onClick={handleClose} className={styles.startMenu}>
					<MenuListItem
						className={styles.startMenuItem}
						onClick={() => scrollTo("bio", 100)}
					>
						👨‍💻 Profile
					</MenuListItem>
					<MenuListItem
						className={styles.startMenuItem}
						onClick={() => scrollTo("skills", 150)}
					>
						⚔️ Skills
					</MenuListItem>
					<MenuListItem
						className={styles.startMenuItem}
						onClick={() => scrollTo("experience", 150)}
					>
						💼 Experience
					</MenuListItem>
					<MenuListItem
						className={styles.startMenuItem}
						onClick={() => scrollTo("projects", 150)}
					>
						🚀 Projects
					</MenuListItem>
					<Separator />
					<MenuListItem
						className={styles.startMenuItem}
						onClick={() => scrollTo("projectUrls", 150)}
					>
						🔗 Project Links
					</MenuListItem>
				</MenuList>
			)}
			<Button
				onClick={handleClick}
				active={isOpen}
				className={styles.startButton}
			>
				<img
					alt="Windows95"
					src="data:image/png;base64,"
					className={styles.winLogo}
				/>
				Start
			</Button>
		</div>
	);
}

const Header = () => (
	<div className={styles.headerBar}>
		<ThemeProvider theme={water}>
			<AppBar $fixed={true}>
				<Toolbar className={styles.toolBar}>
					<Menu />
					<Separator
						size="45px"
						orientation="vertical"
						className={styles.verticalLine}
					/>
					<div className={styles.headerButtonGroup}>
						<Button onClick={() => openLink("https://github.com/mustafacanp")}>
							<span className={styles.buttonText}>Github</span>
						</Button>
						<Button onClick={() => scrollTo("experience", 150)}>
							<span className={styles.buttonText}>Experience</span>
						</Button>
						<Button onClick={() => scrollTo("projects", 150)}>
							<span className={styles.buttonText}>Projects</span>
						</Button>
						<Button
							onClick={() =>
								openLink("mailto:mustafacanpalaz@gmail.com?Subject=Hello")
							}
						>
							<span className={styles.buttonText}>Contact</span>
						</Button>
						<Button onClick={() => openLink("/cmd/", "_blank")}>
							<span
								className={`${styles.buttonText} ${styles.commandLineButton}`}
							>
								<span className={styles.commandLineIcon}>💻</span> Command Line
							</span>
						</Button>
					</div>
					<Avatar square className={styles.headerAvatar} src={ProfileImage} />
				</Toolbar>
			</AppBar>
		</ThemeProvider>
	</div>
);

export default Header;
